for qid, pData in pairs(FOREVER_PAYOFFS) do
    if not Data.QuestPayoffs[qid] then
        Data.QuestPayoffs[qid] = pData
    else
        for k, v in pairs(pData) do
            if not Data.QuestPayoffs[qid][k] then Data.QuestPayoffs[qid][k] = v end
        end
    end
end

